<span class="line"><span style="color:#C678DD;">        if</span><span style="color:#ABB2BF;"> t </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">:</span></span>
