<span class="line"><span style="color:#ABB2BF;">        t_batch </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> torch.</span><span style="color:#61AFEF;">full</span><span style="color:#ABB2BF;">((shape[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">],), t, </span><span style="color:#E06C75;font-style:italic;">dtype</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">torch.long, </span><span style="color:#E06C75;font-style:italic;">device</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">device)</span></span>
